def app_dir():
    """Folder of the program: next to the .exe when packaged, next to this file otherwise."""
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))


def find_ffmpeg():
    p = shutil.which("ffmpeg") or shutil.which("ffmpeg.exe")
    if p:
        return p
    try:
        import imageio_ffmpeg
        return imageio_ffmpeg.get_ffmpeg_exe()
    except Exception:
        return None


def load_audio(path, log=print):
    """Read almost any audio/video file. Returns (samples x channels float32, sample_rate). Keeps the original rate."""
    err = None
    try:                                                   # fast path: wav / flac / ogg / mp3 / aiff / opus ...
        y, sr = sf.read(path, dtype="float32", always_2d=True)
        return np.ascontiguousarray(y), int(sr)
    except Exception as e:
        err = e
    ff = find_ffmpeg()                                     # m4a / aac / wma / mp4 / webm / ... via ffmpeg
    if ff:
        log("  decoding with ffmpeg ...")
        with tempfile.TemporaryDirectory() as td:
            tmp = os.path.join(td, "dec.wav")
            r = subprocess.run([ff, "-v", "error", "-y", "-i", path, "-vn", "-ac", "2", "-c:a", "pcm_f32le", tmp],
                               capture_output=True, text=True)
            if r.returncode == 0 and os.path.isfile(tmp):
                y, sr = sf.read(tmp, dtype="float32", always_2d=True)
                return np.ascontiguousarray(y), int(sr)
            err = RuntimeError(r.stderr.strip()[-300:] or "ffmpeg could not decode it")
    try:                                                   # last resort
        y, sr = librosa.load(path, sr=None, mono=False)
        y = y[np.newaxis, :] if y.ndim == 1 else y
        return np.ascontiguousarray(y.T.astype(np.float32)), int(sr)
    except Exception as e:
        err = err or e
    raise RuntimeError(
        f"Could not read this file ({str(err)[:160]}).\n"
        "If it is m4a / aac / wma / mp4, install the decoder with:  python -m pip install imageio-ffmpeg")


def save_audio(path, y, sr, fmt="WAV 24-bit", log=print):
    ext, how = EXPORT_FORMATS[fmt]
    if isinstance(how, str):                               # written directly by soundfile
        data = y
        if how == "PCM_16":                                # tiny TPDF dither when going down to 16-bit
            rng = np.random.default_rng(0)
            data = y + (rng.random(y.shape) - rng.random(y.shape)).astype(np.float32) / 32768.0
        sf.write(path, np.clip(data, -1.0, 1.0) if how != "FLOAT" else data, sr, subtype=how)
        return
    ff = find_ffmpeg()                                     # lossy formats go through ffmpeg
    if not ff:
        raise RuntimeError(f"Saving as {fmt} needs ffmpeg. Run:  python -m pip install imageio-ffmpeg")
    with tempfile.TemporaryDirectory() as td:
        tmp = os.path.join(td, "x.wav")
        sf.write(tmp, y, sr, subtype="FLOAT")
        r = subprocess.run([ff, "-v", "error", "-y", "-i", tmp] + how + [path], capture_output=True, text=True)
        if r.returncode != 0 or not os.path.isfile(path):
            raise RuntimeError(f"ffmpeg could not write {fmt}: {r.stderr.strip()[-300:]}")


def _db(x):
    return 20 * np.log10(float(np.sqrt(np.mean(np.square(x, dtype=np.float64)))) + 1e-12)


def limit_peaks(y, ceiling, lookahead=0.005, sr=44100):
    """Transparent look-ahead peak limiter: only touches the samples that would go over the ceiling.
    Returns (audio, number of samples touched, deepest reduction in dB)."""
    from scipy.ndimage import minimum_filter1d, uniform_filter1d
    n = max(8, int(lookahead * sr))
    pk = np.max(np.abs(y), axis=1)
    need = np.minimum(1.0, ceiling / np.maximum(pk, 1e-9))
    if need.min() >= 1.0:
        return y, 0, 0.0
    g = minimum_filter1d(need, size=2 * n + 1, mode="nearest")      # reach back/forward over each peak
    g = uniform_filter1d(g, size=2 * n + 1, mode="nearest")         # smooth the gain so it is not audible
    g = np.minimum(g, need)                                         # a peak never gets through
    return (y * g[:, None]).astype(np.float32), int(np.sum(g < 0.999)), float(-20 * np.log10(g.min()))


def match_level(y_out, y_ref, sr, ceiling=0.999, log=print, loudness=True, max_depth_db=10.0):
    """Stretching turns a loud master's flat-topped waveform into taller peaks, so the raw result is either clipped
    or has to be turned down (that is why some outputs came out quieter).
    loudness=True : restore the original loudness and let a light look-ahead limiter catch the taller peaks.
    loudness=False: no limiter - only turn it down as far as needed so nothing clips (cleaner, but quieter)."""
    ref = _db(y_ref)
    if not loudness:
        peak = float(np.abs(y_out).max())
        if peak > ceiling:
            y_out = (y_out * (ceiling / peak)).astype(np.float32)
        log(f"  level: {_db(y_out) - ref:+.2f} dB vs the original (no limiter)")
        return y_out
    gain = float(np.clip(ref - _db(y_out), -6.0, 8.0))
    tried = []
    for _ in range(6):
        y = (y_out * (10 ** (gain / 20))).astype(np.float32)
        y, n_lim, depth = limit_peaks(y, ceiling, sr=sr)
        final = _db(y) - ref
        tried.append((y, final, n_lim, depth))
        if abs(final) < 0.2 or depth > max_depth_db:
            break
        gain = min(gain - final, 8.0)                      # make up for what the limiter took off
    ok = [t for t in tried if t[3] <= max_depth_db] or tried[:1]
    y, final, n_lim, depth = min(ok, key=lambda t: abs(t[1]))
    msg = f"  level: {final:+.2f} dB vs the original"
    if n_lim:
        msg += f" (peaks tamed by up to {depth:.1f} dB)"
    log(msg)
    return y


def build_timemap(beats, head, tail, total_dur, period, keep_edges=False):
    """Source beat times -> evenly spaced target times. With keep_edges the audio before the first beat and
    after the last beat is not stretched at all (1:1)."""
    T = float(period)
    if keep_edges:
        t0 = beats[0]
        tgt = t0 + np.arange(len(beats)) * T
        tgt_end = tgt[-1] + (total_dur - beats[-1])
    else:
        t0 = beats[0] * (T / head)
        tgt = t0 + np.arange(len(beats)) * T
        tgt_end = tgt[-1] + (total_dur - beats[-1]) * (T / tail)
    src = np.concatenate([[0.0], beats, [total_dur]])
    dst = np.concatenate([[0.0], tgt, [tgt_end]])
    keep = np.concatenate([[True], (np.diff(src) > 1e-4) & (np.diff(dst) > 1e-4)])
    return src[keep], dst[keep], tgt_end


def splice_edges(y_out, y_orig, sr, first_t, last_src, last_dst, xf=0.03, guard=0.02, tail_guard=0.10):
    """Put the untouched original audio back before the first beat and after the last beat
    (short crossfades), so vinyl noise / room tone there never goes through the stretcher."""
    out = y_out.copy()
    e = int((first_t - guard) * sr)
    s = e - int(xf * sr)
    if s > 0 and e <= len(out) and e <= len(y_orig):
        out[:s] = y_orig[:s]
        w = np.linspace(0.0, 1.0, e - s)[:, None]
        out[s:e] = (1 - w) * y_orig[s:e] + w * out[s:e]
    s2 = int((last_dst + tail_guard) * sr)
    o2 = int((last_src + tail_guard) * sr)
    n = int(xf * sr)
    m = min(len(out) - s2, len(y_orig) - o2)
    if s2 > 0 and o2 > 0 and m > n:
        w = np.linspace(0.0, 1.0, n)[:, None]
        out[s2:s2 + n] = (1 - w) * out[s2:s2 + n] + w * y_orig[o2:o2 + n]
        out[s2 + n:s2 + m] = y_orig[o2 + n:o2 + m]
    return out


def find_rubberband():
    for here in (app_dir(), getattr(sys, "_MEIPASS", None)):    # next to the program, or bundled inside the exe
        if not here:
            continue
        for name in ("rubberband-r3.exe", "rubberband-r3", "rubberband.exe", "rubberband"):
            p = os.path.join(here, name)
            if os.path.isfile(p):
                return p
    return shutil.which("rubberband-r3") or shutil.which("rubberband") or shutil.which("rubberband.exe")


def stretch_cli(y_st, sr, src, dst, out_len_sec, rb, crisp=False):
    """Offline mode + time map - the method the Rubber Band docs recommend for variable stretching."""
    with tempfile.TemporaryDirectory() as td:
        wi, wo, tm = (os.path.join(td, n) for n in ("in.wav", "out.wav", "map.txt"))
        # The program silently turns the whole file down if the stretched result would clip, which made some
        # songs quieter. Feeding it a -12 dB copy (32-bit float, lossless) avoids that; the gain is restored below.
        sf.write(wi, y_st * 0.25, sr, subtype="FLOAT")
        with open(tm, "w") as f:
            for s, d in zip(src, dst):
                f.write(f"{int(round(s * sr))} {int(round(d * sr))}\n")
        eng = ["-2", "-c", "6"] if crisp else ["-3"]
        if y_st.shape[1] == 2:
            # stretch L and R together. By default the program treats them as two unrelated signals, which smears
            # centred sounds (vocals, kick, bass) across the stereo field like a widener (+8 dB side energy in
            # testing). This matches the CHANNELS_TOGETHER option the pylibrb path uses.
            eng.append("--centre-focus")
        r = subprocess.run([rb] + eng + ["-M", tm, "-D", f"{out_len_sec:.6f}", wi, wo], capture_output=True, text=True)
        if r.returncode != 0 or not os.path.isfile(wo):
            raise RuntimeError("rubberband failed:\n" + r.stderr[-600:])
        y, _ = sf.read(wo, always_2d=True, dtype="float32")
        return y * 4.0


def stretch_pylibrb(y_st, sr, src, dst, out_len_sec, block=2048, crisp=False):
    """Full-quality R3 engine, ratio changed at every beat. (The Python binding can't set Rubber Band's
    keyframe map yet, so this is the next best thing; timing accuracy was identical in testing.)"""
    n, ch = y_st.shape
    opt = Option.PROCESS_REALTIME | Option.CHANNELS_TOGETHER
    opt |= (Option.ENGINE_FASTER | Option.TRANSIENTS_CRISP) if crisp else Option.ENGINE_FINER
    st = RubberBandStretcher(sr, ch, opt, 1.0)
    delay = st.get_start_delay()
    x = np.ascontiguousarray(y_st.T.astype(np.float32))
    s = [int(round(v * sr)) for v in src]
    d = [int(round(v * sr)) for v in dst]
    outs = []
    for k in range(len(s) - 1):
        a, b = s[k], min(s[k + 1], n)
        if b <= a or d[k + 1] <= d[k]:
            continue
        st.time_ratio = (d[k + 1] - d[k]) / (s[k + 1] - s[k])
        for i in range(a, b, block):
            st.process(np.ascontiguousarray(x[:, i:min(i + block, b)]), final=False)
            while st.available() > 0:
                outs.append(st.retrieve_available())
    st.process(np.zeros((ch, block), np.float32), final=True)
    while st.available() > 0:
        outs.append(st.retrieve_available())
    res = np.concatenate(outs, axis=1).T
    want = int(round(out_len_sec * sr))
    res = res[delay:delay + want]
    if len(res) < want:
        res = np.pad(res, ((0, want - len(res)), (0, 0)))
    return res


def time_stretch(y_st, sr, src, dst, out_len_sec, log=print, crisp=False):
    rb = find_rubberband()
    if rb:
        log("  stretching with the Rubber Band program (offline" + (", crisp engine for crackly audio)" if crisp else " R3 + time map)"))
        return stretch_cli(y_st, sr, src, dst, out_len_sec, rb, crisp)
    if HAVE_PYLIBRB:
        log("  stretching with Rubber Band (pylibrb" + (", crisp engine)" if crisp else ", R3)"))
        log("  tip: for the cleanest result on crackly songs, put rubberband.exe next to bpmfix.py")
        return stretch_pylibrb(y_st, sr, src, dst, out_len_sec, crisp=crisp)
    raise RuntimeError("Rubber Band is missing. Run:  python -m pip install pylibrb")


def write_click_check(y_st, sr, times, path):
    mono = y_st.mean(axis=1) if y_st.ndim == 2 else y_st
    clicks = librosa.clicks(times=times, sr=sr, length=len(mono), click_freq=1500, click_duration=0.04)
    mix = 0.8 * mono + 0.6 * clicks
    mix /= max(1.0, np.abs(mix).max())
    sf.write(path, mix, sr, subtype="PCM_16")


def process(path, target_bpm=None, out_path=None, bpm_lo=80.0, bpm_hi=160.0, clicks=False,
            verify=DEFAULTS["verify"], log=print, keep_edges=DEFAULTS["keep_edges"],
            crackle=DEFAULTS["crackle"], fmt=DEFAULTS["fmt"], out_dir=None, loudness=DEFAULTS["loudness"],
            signature=DEFAULTS["signature"], bpm_mode=DEFAULTS["bpm_mode"]):
    log(f"Loading {os.path.basename(path)} ...")
    y_st, sr = load_audio(path, log)                            # samples x channels, original sample rate
    y_mono = y_st.mean(axis=1)
    total = len(y_st) / sr
    log(f"  {total:.1f} s, {sr} Hz, {y_st.shape[1]} ch")

    log("Finding beats ...")
    raw, down = detect_beats(y_mono, sr, log)
    used = "Beat This!"
    log(f"  {len(raw)} beats" + (f" and {len(down)} bars" if down is not None else " (no bar information)")
        + f" found with {used}")
    ivs = np.diff(raw)
    if len(ivs):
        m_iv = float(np.median(ivs))
        line = f"  tracker beats: usually {m_iv:.3f} s apart ({60 / m_iv:.0f}/min)"
        if down is not None and len(down) >= 3:
            Ls = np.diff(down)
            cnt = np.diff(np.searchsorted(raw, down - 0.3 * m_iv))
            vals, c = np.unique(cnt, return_counts=True)
            top = ", ".join(f"{int(v)} beats x{int(k)}" for v, k in sorted(zip(vals, c), key=lambda z: -z[1])[:3])
            line += f"; bars usually {float(np.median(Ls)):.3f} s ({top} per bar)"
        log(line)
    sig = signature
    if sig == "Auto":
        guess = infer_signature(raw, down)
        if guess:
            sig = guess[0]
            log(f"  time signature (auto): {guess[1]} beats per bar -> {sig}  (choose it yourself if that is wrong)")
        else:
            sig = "4/4"
            log("  time signature: assuming 4/4  (choose it yourself if the song is different)")
    else:
        log(f"  time signature: {sig}")
    spec = sig_spec(sig)

    typed_T = bpm_to_period(float(target_bpm), spec, bpm_mode) if target_bpm else None
    prep = prepare_anchors(raw, down, total, spec, typed_T, bpm_lo, bpm_hi, log)
    mmss = lambda v: f"{int(v) // 60}:{int(v) % 60:02d}"
    for ta, tb, n_add, n_drop in prep["events"][:6]:
        if n_add and not n_drop:
            what = f"filled in {n_add} missed beats (tracker had slipped into half-time or lost the beat)"
        elif n_drop and not n_add:
            what = f"removed {n_drop} extra beats (tracker had slipped into double-time)"
        else:
            what = f"repaired {n_add + n_drop} beats"
        log(f"  fixed {mmss(ta)}-{mmss(tb)}: {what}")
    try:                                                       # level guard: fix runs at a wrong metrical level
        T_ref = pick_reference_period(prep["anchors"], typed_T)
        fixed_anchors, fixes = enforce_level(prep["anchors"], y_mono, sr, T_ref, log)
        for ta, tb, r in fixes:
            log(f"  level guard {mmss(ta)}-{mmss(tb)}: beats there were spaced {r:.2f}x the song's own beat "
                f"(a 3:2 / 2:1 level mix-up) - re-tracked from the audio at the song's own tempo")
        if fixes:
            iv_ = np.diff(fixed_anchors)
            prep["anchors"] = fixed_anchors
            prep["head"], prep["tail"] = float(np.median(iv_[:8])), float(np.median(iv_[-8:]))
    except Exception as e:
        log(f"  (level guard skipped: {type(e).__name__}: {str(e)[:100]})")
    real, mask = refine_beats(prep["anchors"], y_mono, sr, log=log, return_mask=True)
    real = fill_weak_runs(real, mask)                          # soft passages: even spacing instead of noisy guesses
    head, tail = prep["head"], prep["tail"]
    if keep_edges:
        beats = real
    else:
        pre, t = [], real[0] - head
        while t > 0:
            pre.append(t); t -= head
        post, t = [], real[-1] + tail
        while t < total:
            post.append(t); t += tail
        beats = np.array(sorted(pre + list(real) + post))

    iv = np.diff(beats)
    bpm_curve = period_to_bpm(iv, spec, bpm_mode)             # tempo curve in the counting you chose
    med = period_to_bpm(float(np.median(iv)), spec, bpm_mode)
    # the song's own tempo, quoted at the level a person would tap (70-180 felt beats per minute), not at whatever
    # level the grid happens to be counted at
    own_period = float(np.median(iv))
    ref_mode = "felt" if spec["regular"] else "quarter"
    lo_t, hi_t = (70.0, 180.0) if spec["regular"] else (60.0, 180.0)
    while period_to_bpm(own_period, spec, ref_mode) < lo_t:
        own_period /= 2
    while period_to_bpm(own_period, spec, ref_mode) >= hi_t:
        own_period *= 2
    scale = float(np.median(iv)) / own_period
    own_felt, own_quarter = period_to_bpm(own_period, spec, "felt"), period_to_bpm(own_period, spec, "quarter")
    irr_before = irregularity(beats)
    mode_name = "felt beats per minute" if bpm_mode == "felt" else "quarter-note BPM"
    log(f"  the song's own tempo: {own_felt:.2f} felt beats per minute  =  {own_quarter:.2f} quarter-note BPM "
        f"(range {np.percentile(bpm_curve, 2) * scale:.1f}-{np.percentile(bpm_curve, 98) * scale:.1f} in "
        f"{'felt beats' if bpm_mode == 'felt' else 'quarter-note BPM'}, irregularity {irr_before:.1f}%)")
    target = float(target_bpm) if target_bpm else round(med, 2)
    period = bpm_to_period(target, spec, bpm_mode)             # seconds between two anchors in the result
    log(f"Target: {target:.2f} {mode_name}  =  {period_to_bpm(period, spec, 'quarter'):.2f} quarter-note BPM "
        f"(what a DAW shows)" + (f"  =  {period_to_bpm(period, spec, 'felt'):.2f} felt beats per minute"
                                  if bpm_mode == "quarter" else ""))
    mean_ratio = period / own_period
    if not (0.8 <= mean_ratio <= 1.25):
        log(f"  WARNING: your target means stretching this song {mean_ratio:.2f}x on average. The song's own tempo is "
            f"{own_felt:.1f} felt beats per minute ({own_quarter:.1f} quarter-note BPM). If you only want to even out "
            f"the tempo, type {own_felt:.1f} (felt) or {own_quarter:.1f} (quarter notes), or use automatic.")

    rep = stretch_report(beats, period)
    log(f"  stretch: slowest {rep['max_up']:.2f}x, fastest {rep['max_down']:.2f}x, "
        f"{rep['pct_over']:.0f}% of the song stretched by more than 20%")
    for ta, tb, r in rep["ranges"][:8]:
        log(f"  WARNING {mmss(ta)}-{mmss(tb)} is stretched {r:.2f}x - may sound artifacty")
    if len(rep["ranges"]) > 8:
        log(f"  ... and {len(rep['ranges']) - 8} more heavy sections")

    src, dst, out_len = build_timemap(beats, head, tail, total, period, keep_edges)
    log("Time-stretching (a few minutes for a full song) ...")
    y_out = time_stretch(y_st, sr, src, dst, out_len, log, crisp=crackle)
    # The stretcher delays/advances everything by a constant amount; measure it and undo it so beat 1 lands on the grid.
    grid_all = dst[1:-1]
    grid_all = grid_all[(grid_all > 0.3) & (grid_all < out_len - 0.3)]
    mo = measure_offset(y_out.mean(axis=1), sr, grid_all)
    if mo is not None and mo[1] < 0.015 and abs(mo[0]) > 0.002:
        shift = int(round(mo[0] * sr))
        if shift < 0:                                            # hits come too early -> delay the audio
            y_out = np.concatenate([np.zeros((-shift, y_out.shape[1]), np.float32), y_out])
        else:                                                    # hits come too late -> trim the start
            y_out = y_out[shift:]
        log(f"  corrected a constant {mo[0] * 1000:+.0f} ms offset from the stretcher")
    if keep_edges:
        y_out = splice_edges(y_out, y_st, sr, beats[0], beats[-1], dst[-2])
        log("  intro and outro left untouched (not stretched)")
    ceiling = 0.97 if fmt in LOSSY else 0.999                  # lossy encoders need a little headroom
    y_out = match_level(y_out, y_st, sr, ceiling, log, loudness)

    base = os.path.splitext(path)[0]
    ext = EXPORT_FORMATS[fmt][0]
    if not out_path:
        folder = out_dir or os.path.dirname(path)
        name = os.path.splitext(os.path.basename(path))[0]
        out_path = os.path.join(folder, f"{name}_fixed_{fmt_bpm(target)}bpm.{ext}")
    save_audio(out_path, y_out, sr, fmt, log)
    log(f"Saved: {out_path}")

    info = dict(times=beats[:-1], bpm=bpm_curve, target=target, report=rep, tracker=used,
                irr_before=irr_before, align=None, out=out_path, signature=sig, map=(src, dst))

    if verify:
        try:
            log("Verifying the result ...")
            grid = dst[1:-1]
            grid = grid[(grid > 0.2) & (grid < out_len - 0.2)]
            al = grid_alignment(y_out.mean(axis=1), sr, grid)
            if al is None:
                log("  (not enough clear drum hits to check against - listen to the click-check files instead)")
            else:
                pct_all, med_ms, cov = al                       # share of all beats / median offset / share with a clear hit
                acc = 100.0 * pct_all / max(cov, 1e-9)           # of the beats that HAVE a clear hit: how many sit on the grid
                info["align"] = (acc, med_ms, cov)
                log(f"  {cov:.0f}% of the beats have a clear drum hit nearby; of those, {acc:.0f}% sit within 15 ms "
                    f"of the even grid (median offset {med_ms:.1f} ms)")
                if cov < 30:
                    log("  (soft passages have no drum hits to check - listen to the click-check files to be sure)")
                elif acc < 70:
                    log("  WARNING: many hits are off the grid - the beats may have been found wrongly. "
                        "Open the click-check files to hear it.")
        except Exception as e:
            log(f"  (verification skipped: {e})")

    if clicks:
        p1 = f"{base}_check_original_beats.wav"
        write_click_check(y_st, sr, beats, p1)
        p2 = f"{base}_check_output_grid.wav"
        write_click_check(y_out, sr, dst[1:-1], p2)
        p3 = f"{base}_check_debug.txt"
        try:
            with open(p3, "w", encoding="utf-8") as f:
                f.write(f"song: {os.path.basename(path)}  length {total:.1f}s  signature {sig}  bpm-mode {bpm_mode}  "
                        f"target {target}\n")
                f.write("tracker beats: " + " ".join(f"{t:.2f}" for t in raw) + "\n")
                f.write("tracker downbeats: " + (" ".join(f"{t:.2f}" for t in down) if down is not None else "none") + "\n")
                f.write("anchors used: " + " ".join(f"{t:.2f}" for t in beats) + "\n")
                f.write("anchor spacing (s): " + " ".join(f"{t:.2f}" for t in np.diff(beats)) + "\n")
        except Exception:
            pass
        log(f"Check files: {os.path.basename(p1)} (clicks on detected beats of the original), {os.path.basename(p2)}, "
            f"{os.path.basename(p3)} (text: beats and bars found, for troubleshooting)")
    return out_path, info
